package com.rpb.reservation.workforce.payroll.governance;
import static com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.*;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.payroll.supplemental.*;
import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;
import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.util.*;
import org.springframework.stereotype.Component;
/** Builds complete immutable proposals and rechecks their exact source baseline. */
@Component public class PayChangeDrafts {
 private final PayChangeRepository requests;private final PayrollConfigurationRepository configs;private final TemplatePublicationRepository publications;private final WorkforceEmployeeRepository employees;private final Clock clock;
 public PayChangeDrafts(PayChangeRepository requests,PayrollConfigurationRepository configs,TemplatePublicationRepository publications,WorkforceEmployeeRepository employees,Clock clock){this.requests=requests;this.configs=configs;this.publications=publications;this.employees=employees;this.clock=clock;}
 public LocalDate date(CurrentActor actor,Write c){if(c.supplemental()!=null&&!c.supplemental().isEmpty()){if(c.effectiveDate()==null||c.profile()!=null&&!c.effectiveDate().equals(c.profile().effectiveFrom()))throw WorkforceException.invalid();return c.effectiveDate();}if(c.adoptionId()!=null)return c.effectiveDate()==null?LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore"))):c.effectiveDate();if(c.profile()!=null){if(c.effectiveDate()==null||!c.effectiveDate().equals(c.profile().effectiveFrom()))throw WorkforceException.invalid();return c.effectiveDate();}if(c.months()==null||c.months().isEmpty())throw WorkforceException.invalid();var month=PayrollProfileValidation.month(c.months().getFirst().month());var p=effective(configs.employeeProfiles(actor.tenantId(),c.companyId(),c.employeeId()),month.atEndOfMonth());if(p==null)throw new WorkforceException("WORKFORCE_PAYROLL_PROFILE_MISSING",409);return p.effectiveFrom();}
 public Content build(CurrentActor actor,UUID store,LocalDate date,Write c,Request old){
  if(c.upgrade()!=null&&c.effectiveDate()==null)throw WorkforceException.invalid();
  if(c.upgrade()!=null&&c.adoptionId()==null||old!=null&&old.content().upgrade()!=null&&c.upgrade()==null)throw WorkforceException.conflict();var reason=PayrollProfileValidation.text(c.reason(),1000,true);var patch=new ArrayList<Difference>();
  if(c.adoptionId()!=null){if(c.supplemental()!=null&&!c.supplemental().isEmpty()||c.employeeId()!=null||c.profile()!=null||c.derivedRule()==null||(c.months()!=null&&!c.months().isEmpty()))throw WorkforceException.invalid();var a=publications.adoption(actor.tenantId(),store,c.companyId(),c.adoptionId());var current=publications.currentAt(actor.tenantId(),store,a.masterId(),date).orElseThrow(WorkforceException::missing);if(!current.id().equals(a.id()))throw WorkforceException.conflict();var rule=PayrollRules.normalize(c.derivedRule());var upgrade=c.upgrade()==null?null:new TemplateUpgradeSupport(publications,requests).context(actor.tenantId(),store,c.companyId(),a,date,c.upgrade(),rule);diff("rule",a.rule(),rule,patch);return baseline(actor,c.companyId(),null,new Content(null,null,a,rule,List.of(),List.copyOf(patch),reason,"",null,upgrade));}
  if(c.employeeId()==null||c.derivedRule()!=null)throw WorkforceException.invalid();var e=employees.find(actor.tenantId(),c.employeeId()).orElseThrow(WorkforceException::missing);if(date.isBefore(e.hireDate()))throw WorkforceException.invalid();var plans=configs.employeeProfiles(actor.tenantId(),c.companyId(),c.employeeId());var before=effective(plans,date);var exact=plans.stream().filter(p->p.effectiveFrom().equals(date)).findFirst().orElse(null);PayProfile profile=null;
  if(c.profile()!=null){var p=c.profile();if(!c.companyId().equals(p.companyId())||!c.employeeId().equals(p.employeeId())||p.templateId()==null||p.expectedVersion()==null||p.expectedVersion()!=(exact==null?0:exact.version()))throw WorkforceException.conflict();var template=configs.findTemplate(actor.tenantId(),p.templateId()).orElseThrow(WorkforceException::missing);configs.assertTemplateAccess(actor.tenantId(),store,p.templateId(),before!=null&&before.templateId().equals(p.templateId()),date);if(!c.companyId().equals(template.companyId())||(!template.enabled()&&(before==null||!before.templateId().equals(template.id()))))throw WorkforceException.invalid();if(p.expectedTemplateVersion()!=null&&p.expectedTemplateVersion()!=template.version())throw WorkforceException.conflict();if(p.defaultMappingId()!=null||p.expectedDefaultVersion()!=null)throw WorkforceException.invalid();
   var rule=PayrollRules.normalize(p.rule());var cpf=PayrollProfileValidation.cpf(p.cpf(),e.birthDate(),clock);if(cpf.prDocumentId()!=null&&!configs.prDocument(actor.tenantId(),e.id(),cpf.prDocumentId()).orElseThrow(WorkforceException::missing).prEffectiveOn().equals(cpf.prDate()))throw WorkforceException.invalid();var payment=PaymentPreferences.validate(p.payment()==null&&before!=null?before.payment():p.payment());var cdac=CdacPayroll.profile(p.cdac()==null&&before!=null?before.cdac():p.cdac(),cpf,rule);UUID id=exact!=null?exact.id():old!=null&&old.content().profile()!=null?old.content().profile().id():UUID.randomUUID();profile=new PayProfile(id,c.companyId(),e.id(),e.name(),date,template.id(),template.version(),rule,cpf,exact==null?1:exact.version()+1,payment,cdac,new ProfileOrigin(template.name(),template.rule(),null,null));diff("profile",before,profile,patch);
  }else if(old!=null){
   // An omitted proposal is retained, not rebuilt. Never attach its old validation
   // result (including CPF/PR evidence and expected versions) to a new baseline.
   if(old.content().profile()!=null&&!old.content().baselineHash().equals(baselineHash(actor,c.companyId(),c.employeeId(),old.content())))throw WorkforceException.conflict();
   profile=old.content().profile();
  }
  var monthly=new TreeMap<String,MonthChange>();if(old!=null)old.content().months().forEach(m->monthly.put(m.month(),m));
  if(c.months()!=null){if(c.months().size()>24)throw WorkforceException.invalid();var seen=new HashSet<String>();for(var m:c.months()){if(m==null||!seen.add(m.month()))throw WorkforceException.invalid();var month=PayrollProfileValidation.month(m.month());if(month.atEndOfMonth().isBefore(e.hireDate()))throw WorkforceException.invalid();var selected=profile!=null&&!profile.effectiveFrom().isAfter(month.atEndOfMonth())?profile:effective(plans,month.atEndOfMonth());if(selected==null)throw new WorkforceException("WORKFORCE_PAYROLL_PROFILE_MISSING",409);var input=PayrollProfileValidation.input(m.input());WageEvents.month(input.items(),month);var prior=requests.monthlyBaseline(actor.tenantId(),c.companyId(),e.id(),month);if(prior.version()!=input.expectedVersion())throw WorkforceException.conflict();var review=input.cdacReview()!=null?input.cdacReview():Boolean.TRUE.equals(input.cdacAutomatic())?null:prior.cdacReview();var next=new LineInput(e.id(),prior.version()+1,input.workingDays(),input.payableDays(),input.unitsReviewed(),input.specialDaysReviewed(),input.items(),input.note(),review);monthly.put(m.month(),new MonthChange(m.month(),prior,next));}}
  // Explicit monthly writes have just been validated against the current input.
  // Retained entries must still have that same source, even if profile was rebuilt.
  for(var m:monthly.values())if(!m.before().equals(requests.monthlyBaseline(actor.tenantId(),c.companyId(),e.id(),YearMonth.parse(m.month()))))throw WorkforceException.conflict();
  var supplemental=c.supplemental()!=null?SupplementalValidation.proposals(c.supplemental()):old==null?null:old.content().supplemental();if(profile==null&&monthly.isEmpty()&&(supplemental==null||supplemental.isEmpty()))throw WorkforceException.invalid();if(supplemental!=null&&supplemental.stream().anyMatch(p->YearMonth.parse(p.settlementMonth()).atEndOfMonth().isBefore(date)))throw WorkforceException.invalid();if(supplemental!=null)diff("supplemental",old==null?null:old.content().supplemental(),supplemental,patch);if(c.profile()==null&&profile!=null)diff("profile",before,profile,patch);monthly.values().forEach(m->diff("months."+m.month(),m.before(),m.after(),patch));return baseline(actor,c.companyId(),c.employeeId(),new Content(before,profile,null,null,List.copyOf(monthly.values()),List.copyOf(patch),reason,"",null,null,supplemental));
 }
 private Content baseline(CurrentActor actor,UUID company,UUID employee,Content c){return new Content(c.beforeProfile(),c.profile(),c.adoption(),c.derivedRule(),c.months(),c.patch(),c.reason(),baselineHash(actor,company,employee,c),c.profile()==null?null:configs.findTemplate(actor.tenantId(),c.profile().templateId()).orElseThrow(WorkforceException::missing),c.upgrade(),c.supplemental());}
 public String baselineHash(CurrentActor actor,UUID company,UUID employee,Content c){var parts=new ArrayList<Object>();if(c.adoption()!=null){var a=c.adoption();parts.add(publications.latest(actor.tenantId(),a.storeId(),a.masterId()).orElse(null));parts.add(publications.release(actor.tenantId(),a.masterId(),a.releaseVersion()).orElse(null));if(c.upgrade()!=null)parts.add(new TemplateUpgradeSupport(publications,requests).recheck(actor.tenantId(),a,c.upgrade()));}else{parts.add(employees.find(actor.tenantId(),employee).orElse(null));parts.add(requests.companyHistory(actor.tenantId(),employee));parts.add(configs.employeeProfiles(actor.tenantId(),company,employee));if(c.profile()!=null){var template=configs.findTemplate(actor.tenantId(),c.profile().templateId()).orElse(null);parts.add(template);if(template!=null&&template.governanceSource()!=null&&(c.beforeProfile()==null||!c.beforeProfile().templateId().equals(template.id()))){var source=template.governanceSource();var today=LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")));parts.add(publications.currentAt(actor.tenantId(),source.storeId(),source.masterId(),c.profile().effectiveFrom().isBefore(today)?today:c.profile().effectiveFrom()).orElse(null));}if(c.profile().cpf().prDocumentId()!=null)parts.add(configs.prDocument(actor.tenantId(),employee,c.profile().cpf().prDocumentId()).orElse(null));}if(c.supplemental()!=null)parts.add(requests.supplementalSources(actor.tenantId(),company,employee,c.supplemental()));for(var m:c.months())parts.add(requests.monthlyBaseline(actor.tenantId(),company,employee,YearMonth.parse(m.month())));}return requests.hash(parts);}
 public void frozen(CurrentActor actor,Request r){if(r.employeeId()==null)return;var c=r.content();if(c.profile()!=null){var next=configs.employeeProfiles(actor.tenantId(),r.companyId(),r.employeeId()).stream().filter(p->p.effectiveFrom().isAfter(r.effectiveDate())).map(PayProfile::effectiveFrom).min(LocalDate::compareTo).orElse(LocalDate.of(2100,12,31));if(requests.frozen(actor.tenantId(),r.companyId(),r.employeeId(),r.effectiveDate(),next.minusDays(1))||configs.lockedProfile(actor.tenantId(),c.profile().id()))throw new WorkforceException("WORKFORCE_PAYROLL_PROFILE_LOCKED",409);}for(var m:c.months()){var month=YearMonth.parse(m.month());if(requests.frozen(actor.tenantId(),r.companyId(),r.employeeId(),month.atDay(1),month.atEndOfMonth()))throw new WorkforceException("WORKFORCE_PAYROLL_PROFILE_LOCKED",409);}}
 public static PayProfile effective(List<PayProfile> plans,LocalDate date){return plans.stream().filter(p->!p.effectiveFrom().isAfter(date)).max(Comparator.comparing(PayProfile::effectiveFrom)).orElse(null);}
 private static final com.fasterxml.jackson.databind.ObjectMapper MAPPER=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();
 private static void diff(String path,Object before,Object after,List<Difference> result){diffNode(path,MAPPER.valueToTree(before),MAPPER.valueToTree(after),result);}
 private static void diffNode(String path,com.fasterxml.jackson.databind.JsonNode a,com.fasterxml.jackson.databind.JsonNode b,List<Difference> result){if(Objects.equals(a,b))return;if(a!=null&&b!=null&&a.isObject()&&b.isObject()){var keys=new TreeSet<String>();a.fieldNames().forEachRemaining(keys::add);b.fieldNames().forEachRemaining(keys::add);keys.forEach(k->diffNode(path+"."+k,a.get(k),b.get(k),result));}else result.add(new Difference(path,a==null||a.isNull()?null:a.isTextual()?a.asText():a.toString(),b==null||b.isNull()?null:b.isTextual()?b.asText():b.toString()));}
}
